        if demo_out[r][c] == 4:
            output_4s.add((r,c))

new_4s = output_4s - input_4s
print(f"New 4s: {sorted(new_4s)}")

# For each new 4, find potential source by checking common offsets
offset_counts = {}
for nr in new_4s:
    for inp in input_4s:
        dr, dc = nr[0]-inp[0], nr[1]-inp[1]
        offset_counts.setdefault((dr, dc), []).append((nr, inp))

print("\nOffset frequencies:")
for offset, pairs in sorted(offset_counts.items(), key=lambda x: len(x[1]), reverse=True)[:5]:
    print(f"  Offset {offset}: {len(pairs)} matches")
    for nr, inp in pairs[:3]:
        print(f"    ({nr}) from ({inp})")

# Most frequent offsets suggest the transformation
if offset_counts:
    best_offset = max(offset_counts.keys(), key=lambda x: len(offset_counts[x]))
    print(f"\nMost common offset: {best_offset}")

    # Apply this offset and see what we get
    result = [[0]*19 for _ in range(17)]
    for inp in input_4s:
        nr, nc = inp[0]+best_offset[0], inp[1]+best_offset[1]
        if 0 <= nr < 17 and 0 <= nc < 19:
            result[nr][nc] = 4

    # Check overlap with expected
    result_set = {(r,c) for r in range(17) for c in range(19) if result[r][c] == 4}
    match = result_set.intersection(new_4s)
    print(f"Matches expected: {len(match)}/{len(new_4s)}")

