from itertools import permutations

def get_cells(r_band, c_band):
    if r_band == 0:
        r_s = h_divs[0] + 1
    else:
        r_s = h_divs[r_band-1] + 1

    if r_band < len(h_divs):
        r_e = h_divs[r_band] - 1
    else:
        r_e = len(demo_in) - 1

    if c_band == 0:
        c_s = v_divs[0] + 1
    else:
        c_s = v_divs[c_band-1] + 1

    if c_band < len(v_divs):
        c_e = v_divs[c_band] - 1
    else:
        c_e = len(demo_in[0]) - 1

    return demo_in[r_s:r_e+1][c_s:c_e+1]

