for rb in range(len(h_divs)):
    for cb in range(len(v_divs)):
        sub = get_cells(rb, cb)
        has_content = any(any(val != 0 and val != 6 for val in row) for row in sub)
        if has_content:
            cells[(rb, cb)] = sub

