    print(f"  {key}: {value}")

# Now find which cell transforms to which other cell
print("\n=== Checking transformations ===")
for src_key, src_val in cells.items():
    for dst_key, dst_val in cells.items():
        if src_key == dst_key:
            continue

        # Try horizontal flip
        hflipped = horizontal_mirror(src_val)
        match_h = all(all(a == b for a, b in zip(row_a, row_b)) for row_a, row_b in zip(hflipped, dst_val))

        # Try vertical flip
        vflipped = src_val[::-1]
        match_v = all(all(a == b for a, b in zip(row_a, row_b)) for row_a, row_b in zip(vflipped, dst_val))

        # Try both flips
        hvflipped = horizontal_mirror(vflipped)
        match_hv = all(all(a == b for a, b in zip(row_a, row_b)) for row_a, row_b in zip(hvflipped, dst_val))

        # Try rotate 180
        rot180 = src_val[::-1][::-1]
        match_r180 = all(all(a == b for a, b in zip(row_a, row_b)) for row_a, row_b in zip(rot180, dst_val))

        if match_h or match_v or match_hv or match_r180:
            print(f"{src_key} -> {dst_key}:")
            print(f"  H-mirror: {match_h}, V-mirror: {match_v}, HV: {match_hv}, R180: {match_r180}")
